style.css:
/* --- Очень простая тёмная тема для school.mos.ru --- */

html, body {
  background: #0d0d0f !important;
  color: #e5e5e5 !important;
}

/* Общие контейнеры */
*, *::before, *::after {
  background-color: transparent !important;
  color: inherit !important;
  border-color: #444 !important;
}

/* Блоки, панели, карточки */
div, section, main, header, footer, aside, article {
  background: #16181b !important;
}

/* Текст */
p, span, li, label, a, h1, h2, h3, h4, h5, h6 {
  color: #e5e5e5 !important;
}

/* Ссылки — просто немного выделим */
a {
  color: #8ab4ff !important;
}

/* Таблицы */
table {
  background: #121315 !important;
}
th, td {
  border-color: #333 !important;
}

/* Поля ввода */
input, textarea, select {
  background: #191b1d !important;
  color: #e5e5e5 !important;
  border: 1px solid #333 !important;
}

/* Изображения чуть затемняем */
img {
  filter: brightness(0.85) !important;
}

/* Иконки SVG в цвет текста */
svg {
  fill: currentColor !important;
}
